package vn.svframe.svframelib.api.crafting.event; import vn.svframe.svframelib.api.crafting.ingredients.*; import vn.svframe.svframelib.api.crafting.recipes.*; import vn.svframe.svframelib.api.crafting.recipes.vmp.*; import net.minecraft.server.network.ServerPlayerEntity; import vn.svframe.svframelib.fabric.runtime.SVFrameLibEventHub; public class SVFrameCraftItemEvent { private final ServerPlayerEntity trigger; private final SVFrameRecipeInventory resultInventory; private final SVFrameBlueprintInventory otherInventories; private final SVFrameCachedResult cache; private VanillaInventoryMapping mapping; private boolean cancelled; public SVFrameCraftItemEvent(ServerPlayerEntity trigger,SVFrameRecipeInventory result,VanillaInventoryMapping mapping,SVFrameBlueprintInventory other,SVFrameCachedResult cache){this.trigger=trigger;resultInventory=result;this.mapping=mapping;otherInventories=other;this.cache=cache;} public SVFrameRecipeInventory getResultInventory(){return resultInventory;} public SVFrameBlueprintInventory getOtherInventories(){return otherInventories;} public SVFrameCachedResult getCache(){return cache;} public VanillaInventoryMapping getMapping(){return mapping;} public void setMapping(VanillaInventoryMapping m){mapping=m;} public ServerPlayerEntity getTrigger(){return trigger;} public boolean isCancelled(){return cancelled;} public void setCancelled(boolean v){cancelled=v;} public void call(){SVFrameLibEventHub.events().publish(this);} }
